<script setup lang="ts">
definePageMeta({ layout: 'workspace' })
type Issue={id:string;reference_number:number;title:string;description:string;category:string;priority:string;status:string;area:string;assigned_to:string;resolution:string;created_at:string}
const db=useSupabaseClient()
const issues=ref<Issue[]>([])
const loading=ref(true),busy=ref(false),error=ref(''),notice=ref('')
const search=ref(''),filter=ref('all'),selected=ref<Issue|null>(null),creating=ref(false)
const categories=['fault','improvement','idea','task'], priorities=['low','medium','high','critical'],statuses=['new','in_progress','on_hold','resolved','closed']
const blank=()=>({title:'',description:'',category:'improvement',priority:'medium',status:'new',area:'Development',assigned_to:'',resolution:''})
const form=reactive(blank())
const isAdmin=ref(false)
const visible=computed(()=>issues.value.filter(x=>(filter.value==='all'||x.status===filter.value)&&[x.title,x.description,x.area,String(x.reference_number)].join(' ').toLowerCase().includes(search.value.toLowerCase())))
const openCount=computed(()=>issues.value.filter(x=>!['resolved','closed'].includes(x.status)).length)
const urgentCount=computed(()=>issues.value.filter(x=>['high','critical'].includes(x.priority)&&!['resolved','closed'].includes(x.status)).length)
function edit(item:Issue){selected.value=item;creating.value=false;Object.assign(form,{title:item.title,description:item.description,category:item.category,priority:item.priority,status:item.status,area:item.area,assigned_to:item.assigned_to,resolution:item.resolution})}
function add(){selected.value=null;creating.value=true;Object.assign(form,blank())}
function close(){creating.value=false;selected.value=null}
async function load(){loading.value=true;error.value='';try{const {data:admin,error:authError}=await db.rpc('is_platform_admin');if(authError)throw authError;isAdmin.value=admin===true;if(!isAdmin.value)throw new Error('Platform administrator access required');const {data,error:e}=await db.from('management_issues').select('*').order('reference_number',{ascending:true});if(e)throw e;issues.value=data||[]}catch(e:any){error.value=e.message||'Unable to load development items'}finally{loading.value=false}}
async function save(){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{const {data:{user}}=await db.auth.getUser();if(!user)throw new Error('Please sign in');const values={title:form.title.trim(),description:form.description.trim(),category:form.category,priority:form.priority,status:form.status,area:form.area.trim()||'Development',assigned_to:form.assigned_to.trim(),resolution:form.resolution.trim(),updated_by:user.id};if(values.title.length<3)throw new Error('Title must be at least three characters');const result=selected.value?await db.from('management_issues').update(values).eq('id',selected.value.id):await db.from('management_issues').insert({...values,created_by:user.id});if(result.error)throw result.error;close();notice.value='Development item saved';await load()}catch(e:any){error.value=e.message||'Unable to save'}finally{busy.value=false}}
onMounted(load)
</script>
<template>
  <div class="space-y-6">
    <UiPageHeader title="Issues & New Features" description="Track the School Sports Tracker rebuild, feature requests, bugs and development workflows.">
      <template #actions><button v-if="isAdmin" class="rounded-xl bg-blue-600 px-5 py-3 text-sm font-bold text-white hover:bg-blue-700" @click="add">+ New item</button></template>
    </UiPageHeader>
    <p v-if="error" role="alert" class="rounded-xl bg-red-50 p-4 text-red-700">{{error}}</p>
    <p v-if="notice" role="status" class="text-green-700">{{notice}}</p>
    <div class="grid gap-4 sm:grid-cols-3"><UiStatCard title="Total development items" :value="issues.length"/><UiStatCard title="Open / planned" :value="openCount"/><UiStatCard title="High priority open" :value="urgentCount"/></div>
    <UiPanel>
      <div class="mb-5 flex flex-wrap gap-3"><input v-model="search" type="search" placeholder="Search issues, features or phases" aria-label="Search development items" class="min-w-48 flex-1 rounded-xl border border-[var(--border)] bg-[var(--surface)] px-4 py-3 text-sm"/><select v-model="filter" aria-label="Filter by status" class="rounded-xl border border-[var(--border)] bg-[var(--surface)] px-4 py-3 text-sm"><option value="all">All statuses</option><option v-for="s in statuses" :key="s" :value="s">{{s.replaceAll('_',' ')}}</option></select></div>
      <p v-if="loading">Loading development tracker…</p>
      <div v-else class="divide-y divide-[var(--border)]"><button v-for="item in visible" :key="item.id" class="flex w-full flex-wrap items-center gap-3 py-4 text-left hover:opacity-75" @click="edit(item)"><span class="w-16 shrink-0 text-xs font-semibold text-[var(--muted)]">#{{item.reference_number}}</span><span class="min-w-48 flex-1"><strong class="block text-sm">{{item.title}}</strong><span class="text-xs text-[var(--muted)]">{{item.area}} · {{item.category}}</span></span><span class="rounded-full border border-[var(--border)] px-3 py-1 text-xs capitalize">{{item.priority}}</span><span class="min-w-24 rounded-full bg-[var(--surface)] px-3 py-1 text-center text-xs capitalize">{{item.status.replaceAll('_',' ')}}</span></button><p v-if="!visible.length" class="py-8 text-center text-sm text-[var(--muted)]">No matching development items.</p></div>
    </UiPanel>
    <div v-if="creating||selected" class="fixed inset-0 z-50 grid place-items-center bg-black/60 p-4" @click.self="close"><section role="dialog" aria-modal="true" aria-label="Development item" class="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-[var(--surface)] p-6 text-[var(--ink)] shadow-xl"><div class="mb-5 flex justify-between"><h2 class="text-xl font-bold">{{creating?'New development item':'Development item #'+selected?.reference_number}}</h2><button aria-label="Close" @click="close">✕</button></div><form class="grid gap-4" @submit.prevent="save"><label class="text-sm font-semibold">Title<input v-model="form.title" required minlength="3" maxlength="180" class="mt-1 w-full rounded-lg border border-[var(--border)] bg-[var(--panel)] p-3"/></label><label class="text-sm font-semibold">Description<textarea v-model="form.description" rows="5" class="mt-1 w-full rounded-lg border border-[var(--border)] bg-[var(--panel)] p-3"/></label><div class="grid gap-3 sm:grid-cols-3"><label v-for="field in ['category','priority','status']" :key="field" class="text-sm font-semibold capitalize">{{field}}<select v-model="form[field as 'category'|'priority'|'status']" class="mt-1 w-full rounded-lg border border-[var(--border)] bg-[var(--panel)] p-3"><option v-for="v in field==='category'?categories:field==='priority'?priorities:statuses" :key="v" :value="v">{{v.replaceAll('_',' ')}}</option></select></label></div><label class="text-sm font-semibold">Area / workflow<input v-model="form.area" class="mt-1 w-full rounded-lg border border-[var(--border)] bg-[var(--panel)] p-3"/></label><label class="text-sm font-semibold">Assigned to<input v-model="form.assigned_to" class="mt-1 w-full rounded-lg border border-[var(--border)] bg-[var(--panel)] p-3"/></label><label class="text-sm font-semibold">Resolution / progress notes<textarea v-model="form.resolution" rows="3" class="mt-1 w-full rounded-lg border border-[var(--border)] bg-[var(--panel)] p-3"/></label><div class="flex justify-end gap-3"><button type="button" class="rounded-xl border border-[var(--border)] px-5 py-3" @click="close">Cancel</button><button :disabled="busy" class="rounded-xl bg-blue-600 px-5 py-3 font-semibold text-white disabled:opacity-50">{{busy?'Saving…':'Save item'}}</button></div></form></section></div>
  </div>
</template>
